import{_ as t,o as n,c as s,ai as e}from"./chunks/framework.BBSijY9B.js";const g=JSON.parse('{"title":"模板：社交动态监测","description":"追踪关键词、提及和评论，汇总值得关注的讨论并起草回复。","frontmatter":{"related":["/templates/content-editor","/automation/routines"],"template":"social-monitor","title":"模板：社交动态监测","description":"追踪关键词、提及和评论，汇总值得关注的讨论并起草回复。","section":"templates","order":5,"role":"社交动态监测员","type":"单 Bot 模板","tags":["模板","社交媒体","X","监测"],"sources":["https://cursor.com/docs/grok-bot/work","https://docs.x.ai/grok-bot/skills-routines-and-automations"],"wordCount":164,"readingTime":1,"head":[["meta",{"property":"og:type","content":"article"}],["meta",{"property":"og:title","content":"模板：社交动态监测 | WANGXXXL"}],["meta",{"property":"og:description","content":"追踪关键词、提及和评论，汇总值得关注的讨论并起草回复。"}],["meta",{"property":"og:url","content":"https://wangxxxl.com/templates/social-monitor"}],["meta",{"property":"og:image","content":"https://wangxxxl.com/og/templates-social-monitor-0a3bc82953.png"}],["meta",{"property":"og:image:alt","content":"模板：社交动态监测 · WANGXXXL · wangxxxl.com"}],["meta",{"name":"twitter:title","content":"模板：社交动态监测 | WANGXXXL"}],["meta",{"name":"twitter:description","content":"追踪关键词、提及和评论，汇总值得关注的讨论并起草回复。"}],["meta",{"name":"twitter:image","content":"https://wangxxxl.com/og/templates-social-monitor-0a3bc82953.png"}],["meta",{"name":"twitter:image:alt","content":"模板：社交动态监测 · WANGXXXL · wangxxxl.com"}],["link",{"rel":"canonical","href":"https://wangxxxl.com/templates/social-monitor"}]]},"headers":[],"relativePath":"templates/social-monitor.md","filePath":"templates/social-monitor.md","lastUpdated":1792485206000}'),o={name:"templates/social-monitor.md"};function l(p,a,i,r,c,m){return n(),s("div",null,[...a[0]||(a[0]=[e(`<h1 id="模板-社交动态监测" tabindex="-1">模板：社交动态监测 <a class="header-anchor" href="#模板-社交动态监测" aria-label="Permalink to &quot;模板：社交动态监测&quot;">​</a></h1><ul><li><strong>角色</strong>：社交动态监测员</li><li><strong>类型</strong>：单 Bot 模板（建议配定时例程）</li><li><strong>需要的连接</strong>：X；可选其他平台（通过浏览器访问）</li><li><strong>适合谁</strong>：需要关注口碑、行业讨论或个人账号互动的人</li></ul><h2 id="提示词" tabindex="-1">提示词 <a class="header-anchor" href="#提示词" aria-label="Permalink to &quot;提示词&quot;">​</a></h2><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>你的岗位是&quot;社交动态监测员&quot;。请记住以下规则：</span></span>
<span class="line"><span></span></span>
<span class="line"><span>【监测范围】</span></span>
<span class="line"><span>- 关键词：（填写，如产品名、个人名、行业话题词，3-8 个）</span></span>
<span class="line"><span>- 账号：（填写需要关注的 5-10 个账号）</span></span>
<span class="line"><span>- 我自己账号收到的提及和回复</span></span>
<span class="line"><span></span></span>
<span class="line"><span>【每次汇总】</span></span>
<span class="line"><span>1. 值得关注的讨论（最多 10 条）：内容摘要、作者、互动量、链接、为什么值得看。</span></span>
<span class="line"><span>2. 情绪概览：正面 / 中性 / 负面的大致情况，负面内容单独列出。</span></span>
<span class="line"><span>3. 建议回复：对需要我回应的提及，各起草一条回复（只给草稿）。</span></span>
<span class="line"><span></span></span>
<span class="line"><span>【边界】</span></span>
<span class="line"><span>- 不得发帖、回复、点赞、转发或私信。</span></span>
<span class="line"><span>- 不对任何人做身份推测。</span></span>
<span class="line"><span>- 数据只来自实际查到的内容，不估算&quot;总讨论量&quot;之类的数字。</span></span></code></pre></div><h2 id="搭配例程" tabindex="-1">搭配例程 <a class="header-anchor" href="#搭配例程" aria-label="Permalink to &quot;搭配例程&quot;">​</a></h2><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>每天中午 12 点和晚上 9 点各汇总一次，发在这个对话里。</span></span></code></pre></div><h2 id="如何定制" tabindex="-1">如何定制 <a class="header-anchor" href="#如何定制" aria-label="Permalink to &quot;如何定制&quot;">​</a></h2><ul><li><strong>紧急提醒</strong>：加一条&quot;出现负面且互动量明显高于平时的内容时，在汇总开头标注【需关注】&quot;。</li><li><strong>降噪</strong>：列出需要排除的关键词组合，减少无关结果。</li><li><strong>频率与用量</strong>：监测频率越高，用量消耗越大，一般一天一到两次足够。</li></ul>`,8)])])}const h=t(o,[["render",l]]);export{g as __pageData,h as default};
